-- UUIDs are generated by PostgreSQL 13+. btree_gist supports the overlap constraints below.
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE users (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    firebase_uid varchar(128) NOT NULL UNIQUE,
    email varchar(320) NOT NULL UNIQUE,
    full_name varchar(120) NOT NULL,
    phone varchar(32),
    status varchar(16) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'DISABLED')),
    email_verified boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE clinics (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    name varchar(160) NOT NULL,
    slug varchar(180) NOT NULL UNIQUE,
    address_line varchar(300),
    city varchar(100),
    region varchar(100),
    postal_code varchar(24),
    country_code char(2) NOT NULL DEFAULT 'IN',
    phone varchar(32),
    timezone varchar(64) NOT NULL DEFAULT 'Asia/Kolkata',
    logo_storage_key varchar(512),
    active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE clinic_members (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid NOT NULL REFERENCES clinics(id) ON DELETE RESTRICT,
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    role varchar(16) NOT NULL CHECK (role IN ('PATIENT', 'DOCTOR', 'STAFF')),
    active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (clinic_id, user_id),
    UNIQUE (clinic_id, id)
);
CREATE INDEX idx_clinic_members_user ON clinic_members(user_id, active);

CREATE TABLE staff_permissions (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid NOT NULL,
    clinic_member_id uuid NOT NULL,
    permission varchar(64) NOT NULL,
    granted_by_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    created_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (clinic_id, clinic_member_id) REFERENCES clinic_members(clinic_id, id) ON DELETE CASCADE,
    UNIQUE (clinic_member_id, permission)
);

CREATE TABLE staff_invitations (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid NOT NULL REFERENCES clinics(id) ON DELETE RESTRICT,
    invited_email varchar(320) NOT NULL,
    token_hash varchar(128) NOT NULL UNIQUE,
    designation varchar(100),
    expires_at timestamptz NOT NULL,
    accepted_at timestamptz,
    revoked_at timestamptz,
    invited_by_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_staff_invitations_email ON staff_invitations(lower(invited_email), expires_at) WHERE accepted_at IS NULL AND revoked_at IS NULL;

CREATE TABLE staff_invitation_permissions (
    invitation_id uuid NOT NULL REFERENCES staff_invitations(id) ON DELETE CASCADE,
    permission varchar(64) NOT NULL,
    PRIMARY KEY (invitation_id, permission)
);

CREATE TABLE patient_profiles (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL UNIQUE REFERENCES users(id) ON DELETE RESTRICT,
    date_of_birth date,
    sex_at_birth varchar(24),
    preferred_name varchar(120),
    emergency_contact_name varchar(120),
    emergency_contact_phone varchar(32),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE doctor_profiles (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid NOT NULL,
    clinic_member_id uuid NOT NULL UNIQUE,
    specialization varchar(120),
    qualification varchar(240),
    registration_number varchar(80),
    consultation_fee numeric(12,2) NOT NULL DEFAULT 0 CHECK (consultation_fee >= 0),
    consultation_duration_minutes integer NOT NULL DEFAULT 20 CHECK (consultation_duration_minutes BETWEEN 5 AND 240),
    active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (clinic_id, clinic_member_id) REFERENCES clinic_members(clinic_id, id) ON DELETE RESTRICT,
    UNIQUE (clinic_id, id)
);

CREATE TABLE staff_profiles (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid NOT NULL,
    clinic_member_id uuid NOT NULL UNIQUE,
    designation varchar(100),
    active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (clinic_id, clinic_member_id) REFERENCES clinic_members(clinic_id, id) ON DELETE RESTRICT,
    UNIQUE (clinic_id, id)
);

CREATE TABLE clinic_patients (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid NOT NULL REFERENCES clinics(id) ON DELETE RESTRICT,
    patient_profile_id uuid NOT NULL REFERENCES patient_profiles(id) ON DELETE RESTRICT,
    patient_code varchar(48) NOT NULL,
    registered_at timestamptz NOT NULL DEFAULT now(),
    active boolean NOT NULL DEFAULT true,
    UNIQUE (clinic_id, patient_profile_id),
    UNIQUE (clinic_id, patient_code),
    UNIQUE (clinic_id, id)
);

CREATE TABLE family_members (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid NOT NULL,
    clinic_patient_id uuid NOT NULL,
    full_name varchar(120) NOT NULL,
    relationship varchar(48) NOT NULL,
    date_of_birth date,
    phone varchar(32),
    authorized_by_patient boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (clinic_id, clinic_patient_id) REFERENCES clinic_patients(clinic_id, id) ON DELETE RESTRICT,
    UNIQUE (clinic_id, id),
    UNIQUE (clinic_id, clinic_patient_id, id)
);

CREATE TABLE doctor_schedules (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid NOT NULL,
    doctor_profile_id uuid NOT NULL,
    weekday smallint NOT NULL CHECK (weekday BETWEEN 0 AND 6),
    starts_at time NOT NULL,
    ends_at time NOT NULL,
    slot_duration_minutes integer NOT NULL CHECK (slot_duration_minutes BETWEEN 5 AND 240),
    effective_from date NOT NULL,
    effective_until date,
    active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    CHECK (ends_at > starts_at),
    CHECK (effective_until IS NULL OR effective_until >= effective_from),
    FOREIGN KEY (clinic_id, doctor_profile_id) REFERENCES doctor_profiles(clinic_id, id) ON DELETE RESTRICT,
    UNIQUE (clinic_id, doctor_profile_id, id)
);
CREATE INDEX idx_doctor_schedules_active ON doctor_schedules(clinic_id, doctor_profile_id, weekday, effective_from) WHERE active;

CREATE TABLE schedule_breaks (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    schedule_id uuid NOT NULL REFERENCES doctor_schedules(id) ON DELETE CASCADE,
    starts_at time NOT NULL,
    ends_at time NOT NULL,
    label varchar(80),
    CHECK (ends_at > starts_at)
);

CREATE TABLE appointment_slots (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid NOT NULL,
    doctor_profile_id uuid NOT NULL,
    schedule_id uuid,
    starts_at timestamptz NOT NULL,
    ends_at timestamptz NOT NULL,
    status varchar(16) NOT NULL DEFAULT 'AVAILABLE' CHECK (status IN ('AVAILABLE', 'HELD', 'BOOKED', 'BLOCKED')),
    hold_expires_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    CHECK (ends_at > starts_at),
    FOREIGN KEY (clinic_id, doctor_profile_id) REFERENCES doctor_profiles(clinic_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (clinic_id, doctor_profile_id, schedule_id) REFERENCES doctor_schedules(clinic_id, doctor_profile_id, id) ON DELETE RESTRICT,
    UNIQUE (clinic_id, doctor_profile_id, starts_at),
    UNIQUE (clinic_id, id),
    UNIQUE (clinic_id, doctor_profile_id, id),
    EXCLUDE USING gist (clinic_id WITH =, doctor_profile_id WITH =, tstzrange(starts_at, ends_at, '[)') WITH &&)
);
CREATE INDEX idx_appointment_slots_open ON appointment_slots(clinic_id, doctor_profile_id, starts_at) WHERE status = 'AVAILABLE';

CREATE TABLE appointments (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid NOT NULL,
    clinic_patient_id uuid NOT NULL,
    doctor_profile_id uuid NOT NULL,
    slot_id uuid NOT NULL,
    family_member_id uuid,
    booked_by_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    starts_at timestamptz NOT NULL,
    ends_at timestamptz NOT NULL,
    status varchar(20) NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'CONFIRMED', 'CHECKED_IN', 'IN_CONSULTATION', 'COMPLETED', 'CANCELLED', 'REJECTED', 'NO_SHOW')),
    reason varchar(500),
    cancellation_reason varchar(500),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CHECK (ends_at > starts_at),
    FOREIGN KEY (clinic_id, clinic_patient_id) REFERENCES clinic_patients(clinic_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (clinic_id, doctor_profile_id) REFERENCES doctor_profiles(clinic_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (clinic_id, doctor_profile_id, slot_id) REFERENCES appointment_slots(clinic_id, doctor_profile_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (clinic_id, clinic_patient_id, family_member_id) REFERENCES family_members(clinic_id, clinic_patient_id, id) ON DELETE RESTRICT,
    UNIQUE (clinic_id, id),
    UNIQUE (clinic_id, id, clinic_patient_id)
);
CREATE UNIQUE INDEX idx_appointments_active_slot ON appointments(clinic_id, slot_id)
    WHERE status IN ('PENDING', 'CONFIRMED', 'CHECKED_IN', 'IN_CONSULTATION');
ALTER TABLE appointments ADD CONSTRAINT ex_appointments_doctor_time
    EXCLUDE USING gist (clinic_id WITH =, doctor_profile_id WITH =, tstzrange(starts_at, ends_at, '[)') WITH &&)
    WHERE (status IN ('PENDING', 'CONFIRMED', 'CHECKED_IN', 'IN_CONSULTATION'));
CREATE INDEX idx_appointments_clinic_time ON appointments(clinic_id, starts_at, status);
CREATE INDEX idx_appointments_patient_time ON appointments(clinic_id, clinic_patient_id, starts_at DESC);
CREATE INDEX idx_appointments_doctor_time ON appointments(clinic_id, doctor_profile_id, starts_at);

CREATE TABLE appointment_status_history (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid NOT NULL,
    appointment_id uuid NOT NULL,
    previous_status varchar(20),
    new_status varchar(20) NOT NULL,
    changed_by_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    reason varchar(500),
    changed_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (clinic_id, appointment_id) REFERENCES appointments(clinic_id, id) ON DELETE RESTRICT
);

CREATE TABLE appointment_notes (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid NOT NULL,
    appointment_id uuid NOT NULL,
    author_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    note text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (clinic_id, appointment_id) REFERENCES appointments(clinic_id, id) ON DELETE RESTRICT
);

CREATE TABLE consultations (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid NOT NULL,
    appointment_id uuid NOT NULL UNIQUE,
    clinic_patient_id uuid NOT NULL,
    symptoms text,
    observations text,
    diagnosis text,
    treatment_plan text,
    doctor_notes text,
    follow_up_instructions text,
    started_at timestamptz,
    finalized_at timestamptz,
    created_by_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (clinic_id, appointment_id, clinic_patient_id) REFERENCES appointments(clinic_id, id, clinic_patient_id) ON DELETE RESTRICT,
    UNIQUE (clinic_id, id),
    UNIQUE (clinic_id, id, clinic_patient_id)
);

CREATE TABLE patient_vitals (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid NOT NULL,
    consultation_id uuid NOT NULL UNIQUE,
    height_cm numeric(5,2) CHECK (height_cm > 0),
    weight_kg numeric(5,2) CHECK (weight_kg > 0),
    temperature_c numeric(4,1),
    systolic_bp integer CHECK (systolic_bp > 0),
    diastolic_bp integer CHECK (diastolic_bp > 0),
    pulse_bpm integer CHECK (pulse_bpm > 0),
    oxygen_saturation numeric(5,2) CHECK (oxygen_saturation BETWEEN 0 AND 100),
    recorded_by_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    recorded_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (clinic_id, consultation_id) REFERENCES consultations(clinic_id, id) ON DELETE RESTRICT
);

CREATE TABLE prescriptions (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid NOT NULL,
    consultation_id uuid NOT NULL,
    clinic_patient_id uuid NOT NULL,
    prescribed_by_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    status varchar(16) NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'FINALIZED', 'VOID')),
    instructions text,
    finalized_at timestamptz,
    document_storage_key varchar(512),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (clinic_id, consultation_id, clinic_patient_id) REFERENCES consultations(clinic_id, id, clinic_patient_id) ON DELETE RESTRICT,
    UNIQUE (clinic_id, id),
    CHECK ((status = 'FINALIZED') = (finalized_at IS NOT NULL))
);

CREATE TABLE prescription_items (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid NOT NULL,
    prescription_id uuid NOT NULL,
    medicine_name varchar(200) NOT NULL,
    generic_name varchar(200),
    dosage varchar(120) NOT NULL,
    dose_unit varchar(48),
    frequency varchar(120) NOT NULL,
    duration varchar(120) NOT NULL,
    route varchar(80),
    food_instruction varchar(24) CHECK (food_instruction IN ('BEFORE_FOOD', 'AFTER_FOOD', 'WITH_FOOD', 'ANYTIME')),
    quantity varchar(80),
    additional_instructions text,
    starts_on date,
    ends_on date,
    position integer NOT NULL CHECK (position >= 0),
    FOREIGN KEY (clinic_id, prescription_id) REFERENCES prescriptions(clinic_id, id) ON DELETE RESTRICT,
    CHECK (ends_on IS NULL OR starts_on IS NULL OR ends_on >= starts_on),
    UNIQUE (prescription_id, position)
);

CREATE TABLE prescription_amendments (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid NOT NULL,
    prescription_id uuid NOT NULL,
    authored_by_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    reason varchar(500) NOT NULL,
    prior_contents jsonb NOT NULL,
    amended_contents jsonb NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (clinic_id, prescription_id) REFERENCES prescriptions(clinic_id, id) ON DELETE RESTRICT
);

CREATE TABLE medical_reports (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid NOT NULL,
    clinic_patient_id uuid NOT NULL,
    consultation_id uuid,
    uploaded_by_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    category varchar(40) NOT NULL CHECK (category IN ('LAB', 'IMAGING', 'XRAY', 'BLOOD_TEST', 'OTHER')),
    description varchar(500),
    original_filename varchar(255) NOT NULL,
    content_type varchar(100) NOT NULL,
    size_bytes bigint NOT NULL CHECK (size_bytes BETWEEN 1 AND 52428800),
    storage_key varchar(512) NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (clinic_id, clinic_patient_id) REFERENCES clinic_patients(clinic_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (clinic_id, consultation_id, clinic_patient_id) REFERENCES consultations(clinic_id, id, clinic_patient_id) ON DELETE RESTRICT,
    UNIQUE (clinic_id, storage_key),
    UNIQUE (clinic_id, id)
);
CREATE INDEX idx_medical_reports_patient ON medical_reports(clinic_id, clinic_patient_id, created_at DESC);

CREATE TABLE medical_history (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid NOT NULL,
    clinic_patient_id uuid NOT NULL,
    category varchar(48) NOT NULL,
    description text NOT NULL,
    recorded_by_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    recorded_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (clinic_id, clinic_patient_id) REFERENCES clinic_patients(clinic_id, id) ON DELETE RESTRICT
);

CREATE TABLE patient_allergies (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid NOT NULL,
    clinic_patient_id uuid NOT NULL,
    allergen varchar(160) NOT NULL,
    reaction varchar(300),
    severity varchar(24) CHECK (severity IN ('MILD', 'MODERATE', 'SEVERE', 'UNKNOWN')),
    notes text,
    recorded_by_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    created_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (clinic_id, clinic_patient_id) REFERENCES clinic_patients(clinic_id, id) ON DELETE RESTRICT,
    UNIQUE (clinic_id, clinic_patient_id, allergen)
);

CREATE TABLE follow_ups (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid NOT NULL,
    consultation_id uuid NOT NULL,
    due_at timestamptz NOT NULL,
    instructions varchar(500),
    status varchar(16) NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN', 'COMPLETED', 'CANCELLED')),
    created_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (clinic_id, consultation_id) REFERENCES consultations(clinic_id, id) ON DELETE RESTRICT
);
CREATE INDEX idx_follow_ups_due ON follow_ups(clinic_id, due_at) WHERE status = 'OPEN';

CREATE TABLE invoices (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid NOT NULL,
    clinic_patient_id uuid NOT NULL,
    appointment_id uuid,
    invoice_number varchar(48) NOT NULL,
    status varchar(16) NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'ISSUED', 'PARTIALLY_PAID', 'PAID', 'VOID')),
    currency char(3) NOT NULL DEFAULT 'INR',
    subtotal numeric(12,2) NOT NULL DEFAULT 0 CHECK (subtotal >= 0),
    tax_total numeric(12,2) NOT NULL DEFAULT 0 CHECK (tax_total >= 0),
    total numeric(12,2) NOT NULL DEFAULT 0 CHECK (total >= 0),
    issued_at timestamptz,
    due_at timestamptz,
    created_by_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (clinic_id, clinic_patient_id) REFERENCES clinic_patients(clinic_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (clinic_id, appointment_id, clinic_patient_id) REFERENCES appointments(clinic_id, id, clinic_patient_id) ON DELETE RESTRICT,
    UNIQUE (clinic_id, invoice_number),
    UNIQUE (clinic_id, id)
);

CREATE TABLE invoice_items (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid NOT NULL,
    invoice_id uuid NOT NULL,
    description varchar(240) NOT NULL,
    quantity numeric(10,2) NOT NULL DEFAULT 1 CHECK (quantity > 0),
    unit_price numeric(12,2) NOT NULL CHECK (unit_price >= 0),
    tax_rate numeric(5,2) NOT NULL DEFAULT 0 CHECK (tax_rate BETWEEN 0 AND 100),
    line_total numeric(12,2) NOT NULL CHECK (line_total >= 0),
    FOREIGN KEY (clinic_id, invoice_id) REFERENCES invoices(clinic_id, id) ON DELETE RESTRICT
);

CREATE TABLE payments (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid NOT NULL,
    invoice_id uuid NOT NULL,
    amount numeric(12,2) NOT NULL CHECK (amount > 0),
    currency char(3) NOT NULL DEFAULT 'INR',
    method varchar(16) NOT NULL CHECK (method IN ('CASH', 'UPI', 'CARD', 'BANK_TRANSFER', 'ONLINE')),
    reference varchar(120),
    status varchar(16) NOT NULL DEFAULT 'RECORDED' CHECK (status IN ('RECORDED', 'PENDING', 'FAILED', 'REFUNDED')),
    received_by_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    received_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (clinic_id, invoice_id) REFERENCES invoices(clinic_id, id) ON DELETE RESTRICT,
    UNIQUE (clinic_id, id)
);

CREATE TABLE refunds (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid NOT NULL,
    payment_id uuid NOT NULL,
    amount numeric(12,2) NOT NULL CHECK (amount > 0),
    reason varchar(500),
    status varchar(16) NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'COMPLETED', 'FAILED')),
    refunded_by_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    created_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (clinic_id, payment_id) REFERENCES payments(clinic_id, id) ON DELETE RESTRICT
);

CREATE TABLE notifications (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid REFERENCES clinics(id) ON DELETE RESTRICT,
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    category varchar(32) NOT NULL,
    title varchar(160) NOT NULL,
    body varchar(1000) NOT NULL,
    read_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_notifications_user_unread ON notifications(user_id, created_at DESC) WHERE read_at IS NULL;

CREATE TABLE notification_preferences (
    user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE RESTRICT,
    email_enabled boolean NOT NULL DEFAULT true,
    sms_enabled boolean NOT NULL DEFAULT false,
    whatsapp_enabled boolean NOT NULL DEFAULT false,
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE notification_logs (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid NOT NULL REFERENCES clinics(id) ON DELETE RESTRICT,
    user_id uuid REFERENCES users(id) ON DELETE RESTRICT,
    channel varchar(16) NOT NULL CHECK (channel IN ('EMAIL', 'SMS', 'WHATSAPP', 'IN_APP')),
    template_key varchar(80) NOT NULL,
    status varchar(16) NOT NULL CHECK (status IN ('QUEUED', 'SENT', 'FAILED')),
    provider_reference varchar(160),
    error_code varchar(80),
    created_at timestamptz NOT NULL DEFAULT now(),
    sent_at timestamptz
);

CREATE TABLE departments (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid NOT NULL REFERENCES clinics(id) ON DELETE RESTRICT,
    name varchar(120) NOT NULL,
    active boolean NOT NULL DEFAULT true,
    UNIQUE (clinic_id, name),
    UNIQUE (clinic_id, id)
);

CREATE TABLE services (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid NOT NULL REFERENCES clinics(id) ON DELETE RESTRICT,
    department_id uuid,
    name varchar(160) NOT NULL,
    description varchar(500),
    fee numeric(12,2) NOT NULL DEFAULT 0 CHECK (fee >= 0),
    active boolean NOT NULL DEFAULT true,
    FOREIGN KEY (clinic_id, department_id) REFERENCES departments(clinic_id, id) ON DELETE RESTRICT,
    UNIQUE (clinic_id, name),
    UNIQUE (clinic_id, id)
);

CREATE TABLE clinic_settings (
    clinic_id uuid NOT NULL REFERENCES clinics(id) ON DELETE RESTRICT,
    setting_key varchar(100) NOT NULL,
    setting_value jsonb NOT NULL,
    updated_by_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    updated_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (clinic_id, setting_key)
);

CREATE TABLE audit_logs (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    clinic_id uuid NOT NULL REFERENCES clinics(id) ON DELETE RESTRICT,
    actor_user_id uuid REFERENCES users(id) ON DELETE RESTRICT,
    action varchar(80) NOT NULL,
    entity_type varchar(80) NOT NULL,
    entity_id uuid,
    before_data jsonb,
    after_data jsonb,
    request_id varchar(80),
    ip_address inet,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_audit_logs_entity ON audit_logs(clinic_id, entity_type, entity_id, created_at DESC);
CREATE INDEX idx_audit_logs_actor ON audit_logs(clinic_id, actor_user_id, created_at DESC);

-- Finalized prescriptions change only through a separate amendment record.
CREATE FUNCTION reject_finalized_prescription_update() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF OLD.finalized_at IS NOT NULL THEN
        RAISE EXCEPTION 'Finalized prescriptions are immutable; record an amendment';
    END IF;
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER trg_prescriptions_immutable
    BEFORE UPDATE OR DELETE ON prescriptions
    FOR EACH ROW EXECUTE FUNCTION reject_finalized_prescription_update();

CREATE FUNCTION reject_finalized_prescription_item_change() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
    target_clinic_id uuid;
    target_prescription_id uuid;
BEGIN
    target_clinic_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.clinic_id ELSE NEW.clinic_id END;
    target_prescription_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.prescription_id ELSE NEW.prescription_id END;
    IF EXISTS (
        SELECT 1 FROM prescriptions
        WHERE clinic_id = target_clinic_id AND id = target_prescription_id AND finalized_at IS NOT NULL
    ) THEN
        RAISE EXCEPTION 'Finalized prescription items are immutable; record an amendment';
    END IF;
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER trg_prescription_items_immutable
    BEFORE INSERT OR UPDATE OR DELETE ON prescription_items
    FOR EACH ROW EXECUTE FUNCTION reject_finalized_prescription_item_change();

CREATE FUNCTION reject_history_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'Historical and audit records are append-only';
    RETURN NULL;
END;
$$;
CREATE TRIGGER trg_prescription_amendments_append_only
    BEFORE UPDATE OR DELETE ON prescription_amendments
    FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
CREATE TRIGGER trg_appointment_history_append_only
    BEFORE UPDATE OR DELETE ON appointment_status_history
    FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
CREATE TRIGGER trg_audit_logs_append_only
    BEFORE UPDATE OR DELETE ON audit_logs
    FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
